// @framerSupportedLayoutWidth any
// @framerSupportedLayoutHeight any
// @framerIntrinsicWidth 320
// @framerIntrinsicHeight 320

/**
 * @framerDisableUnlink
 */

export default function PacmanLoader({
    colorMode = "Original",
    dot5 = "#F58BCB",
    dot4 = "#FF9B42",
    dot3 = "#4C9AFF",
    dot2 = "#FF5A5F",
    dot1 = "#F2D75C",
    speed = 1,
    loop = true,
    style,
}: Props) {
    const containerRef = useRef<HTMLDivElement>(null)

    useEffect(() => {
        if (!containerRef.current) return
        const root = containerRef.current
        root.innerHTML = ""
        const data = JSON.parse(JSON.stringify(animationData))

        // Framer Color controls may provide hex or CSS rgba()/rgb() strings.
        // Parse both formats so control changes are not silently replaced by defaults.
        const parseColor = (value: string, fallback: string): number[] => {
            const input = String(value || fallback).trim()
            const hex = input.match(/^#?([0-9a-f]{3}|[0-9a-f]{6})$/i)
            if (hex) {
                let h = hex[1]
                if (h.length === 3)
                    h = h
                        .split("")
                        .map((c) => c + c)
                        .join("")
                return [0, 2, 4].map(
                    (i) => parseInt(h.slice(i, i + 2), 16) / 255
                )
            }
            const rgb = input.match(
                /rgba?\(\s*([\d.]+)\s*,\s*([\d.]+)\s*,\s*([\d.]+)/i
            )
            if (rgb)
                return [Number(rgb[1]), Number(rgb[2]), Number(rgb[3])].map(
                    (v) => Math.max(0, Math.min(255, v)) / 255
                )
            return parseColor(fallback, "#F2D75C")
        }
        const colors = {
            dot1: parseColor(dot1, "#F2D75C"),
            dot2: parseColor(dot2, "#FF5A5F"),
            dot3: parseColor(dot3, "#4C9AFF"),
            dot4: parseColor(dot4, "#FF9B42"),
            dot5: parseColor(dot5, "#F58BCB"),
        }
        const setLayerFill = (layer: any, rgb: number[]) => {
            const walk = (shapes: any[]) => {
                for (const shape of shapes || []) {
                    if (shape.ty === "fl" && shape.c) {
                        // Replace animated color keyframes too; otherwise Lottie can
                        // overwrite the custom color on the next animation frame.
                        shape.c = { a: 0, k: rgb.slice() }
                    }
                    if (Array.isArray(shape.it)) walk(shape.it)
                }
            }
            walk(layer?.shapes)
        }

        if (colorMode === "Custom") {
            // The source animation's five dot layers, mapped to the five controls.
            const dotLayerColors: Record<string, number[]> = {
                yellow: colors.dot1,
                red: colors.dot2,
                blue: colors.dot3,
                orange: colors.dot4,
                pink: colors.dot5,
            }
            for (const layer of data.layers || []) {
                const rgb = dotLayerColors[layer.nm]
                if (rgb) setLayerFill(layer, rgb)
            }

            // The source Pac-Man fill has color keyframes at frames 45, 75, 105,
            // 135 and 150. Replace each keyframe with the chosen dot color for
            // that interval; preserve the original timing and interpolation data.
            const pacmanLayer = (data.layers || []).find(
                (layer: any) => layer.nm === "Subtract"
            )
            const colorAtFrame = (frame: number): number[] => {
                // Dot 1 is the first (yellow-position) dot. The source animation
                // reaches the following dots at frames 45, 75, 105 and 135.
                if (frame >= 150) return colors.dot1 // loop reset
                if (frame >= 135) return colors.dot5
                if (frame >= 105) return colors.dot4
                if (frame >= 75) return colors.dot3
                if (frame >= 45) return colors.dot2
                return colors.dot1
            }
            const recolorPacman = (shapes: any[]) => {
                for (const shape of shapes || []) {
                    if (shape.ty === "fl" && shape.c) {
                        const fill = shape.c
                        if (fill.a === 1 && Array.isArray(fill.k)) {
                            fill.k = fill.k.map((key: any) => {
                                if (!key || typeof key.t !== "number")
                                    return key
                                const rgb = colorAtFrame(key.t)
                                const next = { ...key }
                                next.s = rgb.slice()
                                if (Array.isArray(key.e)) next.e = rgb.slice()
                                return next
                            })
                        } else {
                            shape.c = { a: 0, k: colors.dot1.slice() }
                        }
                    }
                    if (Array.isArray(shape.it)) recolorPacman(shape.it)
                }
            }
            if (pacmanLayer) recolorPacman(pacmanLayer.shapes)
        } else if (colorMode === "Black" || colorMode === "White") {
            const body = colorMode === "Black" ? [0, 0, 0] : [1, 1, 1]
            const eye = colorMode === "Black" ? [1, 1, 1] : [0, 0, 0]
            for (const layer of data.layers || [])
                setLayerFill(layer, layer.nm === "Ellipse 20" ? eye : body)
        }

        const animation = lottie.loadAnimation({
            container: root,
            renderer: "svg",
            animationData: data,
            autoplay: true,
            loop,
            rendererSettings: {
                preserveAspectRatio: "xMidYMid meet",
                progressiveLoad: false,
            },
        })
        animation.setSpeed(Math.max(0.1, speed))
        return () => animation.destroy()
    }, [speed, loop, colorMode, dot1, dot2, dot3, dot4, dot5])

    return (
        <div
            style={{
                width: "100%",
                height: "100%",
                minWidth: 40,
                minHeight: 40,
                overflow: "hidden",
                display: "flex",
                alignItems: "center",
                justifyContent: "center",
                ...style,
            }}
        >
            <div ref={containerRef} style={{ width: "100%", height: "100%" }} />
        </div>
    )
}

PacmanLoader.defaultProps = {
    width: 320,
    height: 320,
    colorMode: "Original",
    dot1: "#F2D75C",
    dot2: "#FF5A5F",
    dot3: "#4C9AFF",
    dot4: "#FF9B42",
    dot5: "#F58BCB",
    speed: 1,
    loop: true,
}

addPropertyControls(PacmanLoader, {
    colorMode: {
        type: ControlType.Enum,
        title: "Color",
        options: ["Original", "Black", "White", "Custom"],
        optionTitles: ["Original", "Black", "White", "Custom"],
        defaultValue: "Original",
    },
    dot1: {
        type: ControlType.Color,
        title: "Dot 1",
        defaultValue: "#F2D75C",
        hidden: (props) => props.colorMode !== "Custom",
    },
    dot2: {
        type: ControlType.Color,
        title: "Dot 2",
        defaultValue: "#FF5A5F",
        hidden: (props) => props.colorMode !== "Custom",
    },
    dot3: {
        type: ControlType.Color,
        title: "Dot 3",
        defaultValue: "#4C9AFF",
        hidden: (props) => props.colorMode !== "Custom",
    },
    dot4: {
        type: ControlType.Color,
        title: "Dot 4",
        defaultValue: "#FF9B42",
        hidden: (props) => props.colorMode !== "Custom",
    },
    dot5: {
        type: ControlType.Color,
        title: "Dot 5",
        defaultValue: "#F58BCB",
        hidden: (props) => props.colorMode !== "Custom",
    },
    speed: {
        type: ControlType.Number,
        title: "Speed",
        min: 0.25,
        max: 3,
        step: 0.25,
        defaultValue: 1,
    },
    loop: {
        type: ControlType.Boolean,
        title: "Loop",
        description: "Built by Megha.",
        defaultValue: true,
    },
})
